import os
import time
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _to_millis(value: Any) -> Optional[int]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        if value > 10_000_000_000:
            return int(value)
        return int(value * 1000)
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        try:
            n = float(s)
            return int(n if n > 10_000_000_000 else n * 1000)
        except ValueError:
            pass
        try:
            dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return int(dt.timestamp() * 1000)
        except ValueError:
            return None
    return None


def _normalize_events(events: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized = []
    for ev in events:
        normalized.append(
            {
                "logGroupName": ev.get("logGroupName"),
                "logStreamName": ev.get("logStreamName"),
                "timestamp": ev.get("timestamp"),
                "ingestionTime": ev.get("ingestionTime"),
                "message": ev.get("message"),
                "eventId": ev.get("eventId"),
            }
        )
    return normalized


def query_recent_logs(
    log_group_name: str,
    field_filters: Optional[Dict[str, str]] = None,
    start_time: Optional[Any] = None,
    end_time: Optional[Any] = None,
    limit: int = 100,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Retrieve recent Amazon CloudWatch Logs entries filtered by field values and time range.

    Args:
        log_group_name: CloudWatch Logs log group name.
        field_filters: Exact-match field filters applied to the log message body via filter pattern.
                       Example: {"service": "auth", "level": "error"}.
                       These are translated to a CloudWatch Logs filter pattern like:
                       { $.service = "auth" && $.level = "error" }
        start_time: Inclusive start time as epoch seconds/ms, datetime ISO string, or datetime-like string.
        end_time: Exclusive end time as epoch seconds/ms, datetime ISO string, or datetime-like string.
        limit: Maximum number of events to return.
        region_name: AWS region; defaults to AWS_REGION or AWS_DEFAULT_REGION.

    Returns:
        A list of normalized log event dictionaries.
    """
    start_ms = _to_millis(start_time)
    end_ms = _to_millis(end_time)
    if end_ms is None:
        end_ms = int(time.time() * 1000)
    if start_ms is None:
        start_ms = end_ms - 15 * 60 * 1000

    pattern = None
    if field_filters:
        clauses = []
        for key, value in field_filters.items():
            escaped_value = str(value).replace("\\", "\\\\").replace('"', '\\"')
            clauses.append(f'$.{key} = "{escaped_value}"')
        pattern = "{ " + " && ".join(clauses) + " }"

    client = boto3.client("logs", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))

    try:
        if pattern:
            response = client.filter_log_events(
                logGroupName=log_group_name,
                startTime=start_ms,
                endTime=end_ms,
                filterPattern=pattern,
                limit=limit,
            )
            events = response.get("events", [])
            return _normalize_events(events)

        response = client.filter_log_events(
            logGroupName=log_group_name,
            startTime=start_ms,
            endTime=end_ms,
            limit=limit,
        )
        events = response.get("events", [])
        return _normalize_events(events)
    except (ClientError, BotoCoreError):
        return []
